import copy,json,work
P={'required_conditions':['a','b'],'require_verified':True}
R={'claim':'q','conditions':{'a':1,'b':{'x':2},'extra':'ignored'}}
E=[{'source':'unverified-new','claim':'q','value':9,'conditions':{'a':1,'b':{'x':2}},'verified':False,'supersedes':['good']},{'source':'wrong-cond','claim':'q','value':8,'conditions':{'a':1,'b':{'x':3}},'verified':True,'supersedes':['good']},{'source':'good','claim':'q','value':7,'conditions':{'a':1,'b':{'x':2}},'verified':True}]
before=copy.deepcopy((R,E,P))
cases={'ineligible_cannot_supersede':work.evaluate(R,E,P),'missing_sorted':work.evaluate({'claim':'q','conditions':{}},E,P),'no_match':work.evaluate({'claim':'none','conditions':{'a':1,'b':{'x':2}}},E,P),'count_not_authority':work.evaluate(R,[E[2],{'source':'x','claim':'q','value':6,'conditions':{'a':1,'b':{'x':2}},'verified':True},{'source':'y','claim':'q','value':6,'conditions':{'a':1,'b':{'x':2}},'verified':True}],P),'absent_not_zero':work.evaluate({'claim':'calibration','conditions':{'a':1,'b':{'x':2}}},E,P)}
assert before==(R,E,P)
for v in cases.values(): assert set(v)=={'status','value','sources','unknowns'}
print(json.dumps({'cases':cases,'unchanged':True},sort_keys=True))
